while True:
    try:
        line = input().strip()
        if not line:
            continue

        if line[0] == '+':
            # Add command
            name = line[1:]
            participants.add(name)
        elif line[0] == '-':
            # Remove command
            name = line[1:]
            participants.discard(name)
        else:
            # Send command
            if ':' in line:
                sender, message = line.split(':', 1)
                message_length = len(message)
                traffic += message_length * len(participants)
    except EOFError:
        break

print(traffic)
