def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    v = int(next(it))

    sellers = []
    for i in range(n):
        ki = int(next(it))
        prices = [int(next(it)) for _ in range(ki)]
        if any(p < v for p in prices):
            sellers.append(i + 1)  # seller indices are 1-based

    print(len(sellers))
    if sellers:
        print(' '.join(map(str, sellers)))

if __name__ == "__main__":
    solve()
"}

