def find_divisors(s):
    n = len(s)
    divisors = []
    for k in range(1, n + 1):
        if n % k == 0:
            # Check if s is made up of repetitions of s[:k]
            divisor = s[:k]
            if divisor * (n // k) == s:
                divisors.append(divisor)
    return divisors

