def is_divisor(s, candidate):
    """Check if candidate is a divisor of s."""
    if len(s) % len(candidate) != 0:
        return False

    # Check if s is made up of candidate repeated
    for i in range(len(s)):
        if s[i] != candidate[i % len(candidate)]:
            return False

    return True

def count_common_divisors(s1, s2):
    """Count common divisors of s1 and s2."""
    len1, len2 = len(s1), len(s2)

    # Find GCD of lengths
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    g = gcd(len1, len2)

    # Find all divisors of g
    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return sorted(divisors)

    divisors = get_divisors(g)

    # For each divisor, check if there exists a string of that length that is a divisor of both
    count = 0
    for d in divisors:
        # Check all possible substrings of length d
        for i in range(d):
            candidate = s1[i:i+d]
            if is_divisor(s1, candidate) and is_divisor(s2, candidate):
                count += 1
                break  # Only one candidate per divisor length needed

    return count

# Read input
s1 = input().strip()
s2 = input().strip()

# Solve and print
print(count_common_divisors(s1, s2))
"}

