import sys

def is_valid_day(events):
    """Check if a subarray represents a valid day"""
    in_office = set()

    for event in events:
        if event > 0:
            # Entrance
            if event in in_office:
                return False  # Employee entered twice
            in_office.add(event)
        else:
            # Departure
            employee = -event
            if employee not in in_office:
                return False  # Employee left without entering
            in_office.remove(employee)

    return len(in_office) == 0

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    result = []
    i = 0
    while i < n:
        # Try to find the end of the current day
        end = i
        while end < n:
            # Check if the subarray from i to end is a valid day
            if is_valid_day(a[i:end+1]):
                result.append(end - i + 1)
                i = end + 1
                break
            end += 1
        else:
            # No valid day found
            print(-1)
            return

    print(len(result))
    print(' '.join(map(str, result)))

if __name__ == "__main__":
    solve()
"}

