import sys
from collections import defaultdict, deque

def longest_common_subsequence(n, k, permutations):
    # Create position dictionaries for each permutation
    positions = []
    for perm in permutations:
        pos = {}
        for idx, num in enumerate(perm):
            pos[num] = idx
        positions.append(pos)

    # Build adjacency list for the graph
    graph = defaultdict(list)
    for i in range(n):
        for j in range(n):
            if i != j:
                # Check if i appears before j in all permutations
                all_before = True
                for perm_pos in positions:
                    if perm_pos[i] >= perm_pos[j]:
                        all_before = False
                        break
                if all_before:
                    graph[i].append(j)

    # Find longest path using topological sort
    # First, find in-degrees
    in_degree = defaultdict(int)
    for u in graph:
        for v in graph[u]:
            in_degree[v] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(n):
        if in_degree[i] == 0:
            queue.append(i)

    # Longest path
    longest_path = 0
    while queue:
        u = queue.popleft()
        for v in graph[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                queue.append(v)
                # Update longest path
                if len(graph[u]) > longest_path:
                    longest_path = len(graph[u])
                # Actually, we need to track path length more carefully
                # Let me rethink this

    # Better approach: track path lengths from each node
    path_length = [1] * n
    for u in range(n):
        for v in graph[u]:
            path_length[v] = max(path_length[v], path_length[u] + 1)

    return max(path_length)

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])

    permutations = []
    idx = 2
    for _ in range(k):
        perm = list(map(int, data[idx:idx+n]))
        permutations.append(perm)
        idx += n

    result = longest_common_subsequence(n, k, permutations)
    print(result)

if __name__ == "__main__":
    main()
"}

