def solve():
    n = int(input())
    s = input()

    # First, count all regular bracket sequences of length 2n
    dp_total = [0] * (n + 1)
    dp_total[0] = 1

    for i in range(2 * n):
        new_dp = [0] * (n + 1)
        for j in range(n + 1):
            if dp_total[j] == 0:
                continue
            if j < n:
                new_dp[j + 1] = (new_dp[j + 1] + dp_total[j]) % MOD
            new_dp[j - 1] = (new_dp[j - 1] + dp_total[j]) % MOD
        dp_total = new_dp

    # Now count sequences that do NOT contain s as a substring
    len_s = len(s)

    # DP[i][j]: number of sequences of length i with balance j that do NOT contain s as a substring
    dp_no = [[[0] * (len_s + 1) for _ in range(n + 1)] for _ in range(2 * n + 1)]
    dp_no[0][0][0] = 1

    for i in range(2 * n):
        for j in range(n + 1):
            for k in range(len_s):
                if dp_no[i][j][k] == 0:
                    continue

                # Try adding '(' at position i+1
                if j < n:
                    new_k = k
                    # Check if adding '(' would cause s to match
                    if k < len_s - 1 and s[k] == '(':  # not the last character, and matches
                        new_k += 1
                    if k == len_s - 1 and s[k] == '(':  # last character, and matches
                        dp_no[i+1][j+1][0] = (dp_no[i+1][j+1][0] + dp_no[i][j][k]) % MOD
                    else:
                        dp_no[i+1][j+1][new_k] = (dp_no[i+1][j+1][new_k] + dp_no[i][j][k]) % MOD

                # Try adding ')' at position i+1
                if j > 0:
                    new_k = k
                    if k < len_s - 1 and s[k] == ')':
                        new_k += 1
                    if k == len_s - 1 and s[k] == ')':
                        dp_no[i+1][j-1][0] = (dp_no[i+1][j-1][0] + dp_no[i][j][k]) % MOD
                    else:
                        dp_no[i+1][j-1][new_k] = (dp_no[i+1][j-1][new_k] + dp_no[i][j][k]) % MOD

    # The answer is total - no
    answer = (dp_total[n] - dp_no[2 * n][j][0] for j in range(n + 1)) % MOD
    print(answer)

