            for k in range(len_s):
                if dp[i][j][k] == 0:
                    continue

                # Add '(' at position i+1
                if j < n:
                    if k < len_s - 1 and s[k] == '(':  # not the last character, and matches
                        new_k = k + 1
                    elif k == len_s - 1 and s[k] == '(':  # last character, and matches
                        new_k = 0
                    else:
