import sys

def minimal_perimeter(a, b):
    """Find the minimal perimeter of a rectangle that can contain a red rectangle of area a
    and a blue rectangle of area b, such that either a or b forms a rectangle (i.e., is factorable).
    """

    # Function to find all divisors of a number up to sqrt(n)
    def get_divisors(n):
        divisors = set()
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.add(i)
                divisors.add(n // i)
        return sorted(divisors)

    # Check all possible placements where red forms a rectangle
    min_perimeter = float('inf')

    # Red forms a rectangle, try all divisors of a
    divisors_a = get_divisors(a)
    for d in divisors_a:
        h1 = a // d
        # Try placing blue next to red in width
        if b % h1 == 0:
            w = d + b // h1
            h = h1
            perimeter = 2 * (w + h)
            if perimeter < min_perimeter:
                min_perimeter = perimeter

        # Try placing blue on top of red in height
        if b % d == 0:
            w = d
            h = h1 + b // d
            perimeter = 2 * (w + h)
            if perimeter < min_perimeter:
                min_perimeter = perimeter

    # Blue forms a rectangle, try all divisors of b
    divisors_b = get_divisors(b)
    for d in divisors_b:
        h1 = b // d
        # Try placing red next to blue in width
        if a % h1 == 0:
            w = d + a // h1
            h = h1
            perimeter = 2 * (w + h)
            if perimeter < min_perimeter:
                min_perimeter = perimeter

        # Try placing red on top of blue in height
        if a % d == 0:
            w = d
            h = h1 + a // d
            perimeter = 2 * (w + h)
            if perimeter < min_perimeter:
                min_perimeter = perimeter

    return min_perimeter

def main():
    a, b = map(int, sys.stdin.readline().split())
    result = minimal_perimeter(a, b)
    print(result)

if __name__ == "__main__":
    main()
