import sys
import math

def factor(n):
    """Return a list of prime factors of n."""
    factors = []
    # Check for even factors
    while n % 2 == 0:
        factors.append(2)
        n //= 2
    # Check for odd factors
    i = 3
    while i * i <= n:
        while n % i == 0:
            factors.append(i)
            n //= i
        i += 2
    # If n is a prime number greater than 2
    if n > 1:
        factors.append(n)
    return factors

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    t = int(data[0])
    idx = 1
    results = []

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        if n % 2 != 0 and all(n % i != 0 for i in range(3, int(math.sqrt(n)) + 1)):
            # n is prime
            results.append("1\n1")
            continue

        smallest = None
        for p in factor(n):
            if smallest is None:
                smallest = p
            else:
                smallest = min(smallest, p)

        a = smallest
        b = n // a

        if b % a == 0:
            c = b // a
        else:
            c = b

        sequence = [a, b if b % a == 0 else b]

        # Special case: if a is small and c is not divisible by a
        if c > 1 and c % a != 0 and smallest != a:
            c = n // (a * a) * a
            sequence = [a, a, c]

        if c > 1:
            sequence.append(c)

        results.append(str(len(sequence)))
        results.append(" ".join(map(str, sequence)))

    sys.stdout.write("\n".join(results))

if __name__ == "__main__":
    solve()
"}

