def solve():
    n = int(input())
    items = []
    for i in range(n):
        ti, di, pi = map(int, input().split())
        items.append((ti, di, pi, i + 1))  # (time, deadline, value, index)

    # dp[t] = (max_value, path)
    dp = {}
    dp[0] = (0, [])  # base case: 0 time, 0 value, no items

    for ti, di, pi, idx in items:
        if ti > di:
            continue  # can't save this item

        new_dp = {}
        # Option 1: don't take this item
        for t in dp:
            new_dp[t] = max(new_dp.get(t, (0, [])), dp[t])

        # Option 2: take this item
        for t in dp:
            new_t = t + ti
            new_val = dp[t][0] + pi
            new_path = dp[t][1] + [idx]

            # Check if we can take this item
            if new_t <= di:
                new_dp[new_t] = max(new_dp.get(new_t, (0, [])), (new_val, new_path))

        dp = new_dp

    # Find the maximum value
    max_val = 0
    best_path = []
    for t in dp:
        if dp[t][0] > max_val:
            max_val = dp[t][0]
            best_path = dp[t][1]

    print(max_val)
    print(len(best_path))
    if best_path:
        print(' '.join(map(str, best_path)))

solve()
