    n = int(next(it))

    # Build the tree
    tree = [[] for _ in range(n + 1)]
    for i in range(2, n + 1):
        p = int(next(it))
        tree[p].append(i)

    # Initial light states
    light = [0] * (n + 1)
    for i in range(1, n + 1):
        light[i] = int(next(it))

    # Euler Tour to linearize the tree
    in_time = [0] * (n + 1)
    out_time = [0] * (n + 1)
    time = 1

    def dfs(u):
        nonlocal time
        in_time[u] = time
        time += 1
        for v in tree[u]:
            dfs(v)
        out_time[u] = time - 1

    dfs(1)

    class FenwickTree:
        def __init__(self, size):
            self.n = size
            self.tree = [0] * (self.n + 2)

        def update(self, idx, delta):
            while idx <= self.n:
                self.tree[idx] += delta
                idx += idx & -idx

        def query(self, idx):
            res = 0
            while idx > 0:
                res += self.tree[idx]
                idx -= idx & -idx
            return res

        def range_update(self, l, r, delta):
            self.update(l, delta)
            self.update(r + 1, -delta)

        def range_query(self, l, r):
            if l < 1:
                return self.query(r)
            return self.query(r) - self.query(l - 1)

    # We need a different approach
    # For 'get', we just sum light states in the range [l, r]
    # For 'pow', we need to toggle state of all nodes in [l, r]

    # So we maintain an array of light states
    light_array = [0] * (n + 1)
    for i in range(1, n + 1):
