import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    m = int(data[idx]); idx += 1
    t = int(data[idx]); idx += 1

    grid = []
    for i in range(n):
        row = data[idx]
        grid.append(row)
        idx += 1

    # Preprocess: for each cell, determine if it has same-colored neighbors
    has_same_neighbor = [[False] * m for _ in range(n)]
    for i in range(n):
        for j in range(m):
            # Check all 4 adjacent cells
            same = False
            if i > 0 and grid[i][j] == grid[i-1][j]:
                same = True
            elif i < n-1 and grid[i][j] == grid[i+1][j]:
                same = True
            elif j > 0 and grid[i][j] == grid[i][j-1]:
                same = True
            elif j < m-1 and grid[i][j] == grid[i][j+1]:
                same = True

            has_same_neighbor[i][j] = same

    # Process queries
    output = []
    for _ in range(t):
        i = int(data[idx]) - 1; idx += 1
        j = int(data[idx]) - 1; idx += 1
        p = int(data[idx]); idx += 1

        # If it has no same-colored neighbors, it never changes
        if not has_same_neighbor[i][j]:
            output.append(grid[i][j])
            continue

        # If it has same-colored neighbors, it flips once and stays flipped
        if p == 1:
            output.append('1' if grid[i][j] == '0' else '0')
        else:
            output.append('1' if grid[i][j] == '0' else '0')

    sys.stdout.write("\n".join(output))

if __name__ == "__main__":
    solve()
