import sys
import math

def mobius(n):
    if n == 1:
        return 1

    # Factorize n
    factors = set()
    if n % 2 == 0:
        factors.add(2)
        n //= 2
        while n % 2 == 0:
            n //= 2

    i = 3
    while i * i <= n:
        if n % i == 0:
            factors.add(i)
            n //= i
            while n % i == 0:
                n //= i
        i += 2

    if n > 1:
        factors.add(n)

    # If there are repeated prime factors, μ(n) = 0
    if len(factors) != len(set(factors)):
        return 0

    return (-1) ** len(factors)

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Find maximum value
    max_val = max(a) if a else 0

    # Count numbers divisible by each d
    count_div = {}
    for d in range(1, max_val + 1):
        cnt = 0
        for num in freq:
            if num % d == 0:
                cnt += freq[num]
        count_div[d] = cnt

    # Inclusion-exclusion with Möbius function
    MOD = 10**9 + 7
    result = 0

    for d in range(1, max_val + 1):
        mu = mobius(d)
        cnt = count_div[d]

        if mu == 0:
            continue

        # Number of subsequences with all elements divisible by d
        # = 2^(count) - 1 (non-empty subsequences)
        power = pow(2, cnt, MOD)
        result = (result + mu * (power - 1)) % MOD

    print(result % MOD)

if __name__ == "__main__":
    solve()
