def square_free(n):
    """Return the square-free form of n."""
    if n == 1:
        return 1

    # Factorize n
    factors = {}
    temp = n

    # Check for 2
    if temp % 2 == 0:
        factors[2] = 1
        temp //= 2
        while temp % 2 == 0:
            temp //= 2

    # Check for odd primes
    i = 3
    while i * i <= temp:
        if temp % i == 0:
            factors[i] = 1
            temp //= i
            while temp % i == 0:
                temp //= i
        i += 2

    if temp > 1:
        factors[temp] = 1

    # Construct square-free form
    result = 1
    for p in factors:
        result *= p
    return result

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Compute square-free forms
    sq_free = [square_free(x) for x in a]

    # Check for perfect square (1)
    if 1 in sq_free:
        print(1)
        return

    # Check for duplicate
    freq = {}
    for x in sq_free:
        freq[x] = freq.get(x, 0) + 1

    for x, count in freq.items():
        if count >= 2:
            print(2)
            return

    # If n > 8, by pigeonhole principle, there must be a duplicate
    if n > 8:
        print(2)
        return

    # Otherwise, check all non-empty subsets
    from itertools import combinations

    # Try all subsets
    for mask in range(1, 1 << n):
        product = 1
        for i in range(n):
            if mask & (1 << i):
                product *= a[i]

        sqrt_p = int(product ** 0.5)
        if sqrt_p * sqrt_p == product:
            print(1)
            return

    # If we get here, no such subsequence exists
    print(-1)

