import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])
    a = list(map(int, data[2:2+n]))

    # dp[i][j] = maximum sum using first i elements with remainder j
    # We use a 2D list of size (n+1) x m
    dp = [[-1] * m for _ in range(n + 1)]
    dp[0][0] = 0  # Base case: no elements, sum = 0, remainder = 0

    for i in range(1, n + 1):
        val = a[i - 1]
        # Copy previous state
        for j in range(m):
            if dp[i - 1][j] != -1:
                dp[i][j] = dp[i - 1][j]

        # Try adding the current element
        for j in range(m):
            if dp[i - 1][j] != -1:
                new_remainder = (j + val) % m
                new_sum = dp[i - 1][j] + val
                if dp[i][new_remainder] == -1 or new_sum > dp[i][new_remainder]:
                    dp[i][new_remainder] = new_sum

    # Find the maximum remainder
    max_remainder = 0
    for j in range(m):
        if dp[n][j] != -1:
            max_remainder = max(max_remainder, j)

    print(max_remainder)

