    if not data:
        return

    n = int(data[0])
    arr = list(map(int, data[1:1+n]))

    positives = [x for x in arr if x > 0]
    negatives = [x for x in arr if x < 0]
    zeros = [x for x in arr if x == 0]

    # If there are no positives and no negatives, just keep as is
    if not positives and not negatives:
        print(' '.join(map(str, arr)))
        return

    # Change all negatives to positives
    for i in range(len(negatives)):
        arr[arr.index(negatives[i])] = -negatives[i] - 1

    # Now we have only positives and zeros
    # If n is even, we want all negatives (which means we need to change positives to negatives)
    # If n is odd, we need to keep at least one positive

    if n % 2 == 0:
        # Change all positives to negatives
        for i in range(len(positives)):
            arr[arr.index(positives[i])] = -positives[i] - 1
    else:
        # Keep one positive as is, change all others to negatives
        if positives:
            # Keep the largest positive as is
            largest_positive = max(positives)
            idx = arr.index(largest_positive)
            arr[idx] = largest_positive

            # Change other positives to negatives
            for i in range(len(positives)):
                if arr[i] != largest_positive:
                    arr[i] = -arr[i] - 1

