    if not data:
        return

    t = int(data[0])
    idx = 1

    for _ in range(t):
        n = int(data[idx])
        idx += 1

        # Find the smallest prime factor of n
        def smallest_prime_factor(n):
            if n % 2 == 0:
                return 2
            for i in range(3, int(n**0.5) + 1, 2):
                if n % i == 0:
                    return i
            return n

        p = smallest_prime_factor(n)

        # Count how many times p divides n
        count = 0
        while n % p == 0:
            n //= p
            count += 1

        # Construct the sequence
        if count == 1:
            # Just use the prime itself
            print(1)
            print(p)
        else:
            # Use p (count-1) times, then the last term
            print(count)
            print(' '.join([str(p)] * (count - 1) + [str(n)]))

solve()
