def can_reach_zero(angles):
    """Check if we can reach 0 degrees after all rotations."""
    n = len(angles)

    # DP[i][s] = True if we can reach sum s using first i angles
    # We use a set to track reachable sums
    reachable = {0}

    for angle in angles:
        new_reachable = set()
        for s in reachable:
            # Rotate clockwise
            new_reachable.add((s + angle) % 360)
            # Rotate counterclockwise
            new_reachable.add((s - angle) % 360)
        reachable.update(new_reachable)

    return 0 in reachable

n = int(input())
