import sys

MOD = 10**9 + 7

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    max_val = max(a) if a else 0

    # Compute f(d) for all d
    f = {}
    for d in range(1, max_val + 1):
        cnt = 0
        for num in a:
            if num % d == 0:
                cnt += 1
        f[d] = pow(2, cnt, MOD) - 1
        f[d] %= MOD

    # Use inclusion-exclusion to compute g(1)
    # g(d) = f(d) - sum(g[k] for k > d if k % d == 0)
    g = {}
    for d in range(max_val, 0, -1):
        g[d] = f[d]
        for k in range(2 * d, max_val + 1, d):
            g[d] = (g[d] - g[k]) % MOD

    print(g[1])

if __name__ == "__main__":
    solve()
"}

