import sys

def solve():
    n = int(sys.stdin.readline())
    angles = []
    for _ in range(n):
        angles.append(int(sys.stdin.readline()))

    # Check if there's a way to choose signs such that the sum is 0 modulo 360
    # We can use a recursive approach with bitmasking

    def can_reach(target, index, current_sum):
        if index == n:
            return current_sum % 360 == target

        # Try both directions
        return can_reach(target, index + 1, current_sum + angles[index]) or\
               can_reach(target, index + 1, current_sum - angles[index])

    # We need the sum to be 0 modulo 360
    # So we need to check if there's a way to reach 0 from the initial state
    # Start from 0 and try to reach 0 again

    return can_reach(0, 0, 0)

def main():
    if solve():
        print("YES")
    else:
        print("NO")

if __name__ == "__main__":
