    if not data:
        return

    n = int(data[0])
    s = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Sort the array
    a_sorted = sorted(a)

    operations = 0

    # The median position is at n//2
    median_pos = n // 2

    # If the median element is not already s, adjust it
    if a_sorted[median_pos] != s:
        operations += abs(a_sorted[median_pos] - s)

    # Process lower half (0 to n//2 - 1)
    for i in range(median_pos):
        if a_sorted[i] > s:
            operations += a_sorted[i] - s

    # Process upper half (n//2 + 1 to n - 1)
    for i in range(median_pos + 1, n):
        if a_sorted[i] < s:
            operations += s - a_sorted[i]

    print(operations)

