import sys
import math

def is_perfect_square(x):
    """Check if x is a perfect square"""
    s = int(math.isqrt(x))
    return s * s == x

def factorize(x):
    """Return the signature of x: a tuple of exponents modulo 2 for primes up to sqrt(x)"""
    signature = []
    i = 2
    while i * i <= x:
        count = 0
        while x % i == 0:
            count += 1
            x //= i
        signature.append(count % 2)
        i += 1
    if x > 1:
        signature.append(1)
    return tuple(signature)

n = int(sys.stdin.readline())
a = list(map(int, sys.stdin.readline().split()))

# Check for perfect square
for num in a:
    if is_perfect_square(num):
        print(1)
        sys.exit()

# Check for pair with same signature
seen = {}
for num in a:
    sig = factorize(num)
    if sig in seen:
        print(2)
        sys.exit()
    seen[sig] = True

# If we get here, we need to find 3 elements
# or there's no solution
if n >= 3:
    print(3)
else:
    print(-1)
