def solve_brute(n, a):
    max_length = n  # maximum possible (all ones or all twos)

    for i in range(n):
        for j in range(i, n):
            # create reversed segment
            arr = a.copy()
            arr[i:j+1] = arr[i:j+1][::-1]

            # find length of longest non-decreasing subsequence
            length = 0
            current = -1

            for num in arr:
                if num >= current:
                    length += 1
                    current = num

            if length > max_length:
                max_length = length

    return max_length

