import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Strategy:
    # - Keep zero as it is
    # - For negative numbers: keep them negative unless we need to make the product positive
    # - For positive numbers: change to negative
    # - If we need to make the product positive (n odd, odd number of negative), we change a negative to 0

    neg_count = sum(1 for num in a if num < 0)

    # Change positive numbers to negative
    # But for negative numbers, wait until we know we need one to be positive
    result = []

    for num in a:
        result.append(num)

    # Only change positive numbers if the number of negative numbers is odd (since we'll change one later)
    if neg_count % 2 == 1:
        for i in range(n):
            if a[i] < 0 and -a[i] - 1 == 0:
                # If we change this to 0, we fix the parity and get a positive at least one
                result[i] = -a[i] - 1
            elif a[i] > 0:
                result[i] = -a[i] - 1
    else:
        for i in range(n):
            if a[i] > 0:
                result[i] = -a[i] - 1

    # If n is odd, we need the product to be positive, so ensure at least one index is positive
    if n % 2 == 1:
        is_positive = sum(1 for num in result if num > 0)
        if is_positive % 2 == 0:  # Even number of positive means product is negative
            # Change one negative to 0
            for i in range(n):
                if a[i] < 0 and a[i] == -1:  # -1 changes to 0, which is a positive multiplier
                    result[i] = 0
                    break

    print(' '.join(map(str, result)))

if __name__ == '__main__':
    solve()
"}

