def get_prime_factors(n, prime_map):
    """Get the prime factorization of n as a dictionary."""
    factors = {}
    for p in prime_map:
        if p * p > n:
            break
        while n % p == 0:
            factors[p] = factors.get(p, 0) + 1
            n //= p
    if n > 1:
        factors[n] = 1
    return factors

def solve():
    n = int(input())
    a = list(map(int, input().split()))

    # Precompute prime factorizations for numbers up to 10^6
    prime_map = {}
    num = 2
    while num * num <= 10**6:
        prime_map[num] = True
        num += 1

    # Map each number to its signature (bitmask of prime exponents mod 2)
    signatures = {}
    for num in a:
        factors = get_prime_factors(num, prime_map)
        signature = 0
        for p in factors:
            # Use XOR to toggle the bit for this prime
            signature ^= (1 << p)

        if signature == 0:
            # This number is a perfect square
            print(1)
            return

        if signature in signatures:
            # Found two numbers with the same signature
            print(2)
            return
        signatures[signature] = True

    # No perfect square and no matching pair found
    print(-1)

