import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if p[i-1] != 0:
            adj[i].append(p[i-1])
            adj[p[i-1]].append(i)

    # Degree array
    degree = [0] * (n + 1)
    for i in range(1, n + 1):
        degree[i] = len(adj[i])

    # BFS queue
    queue = deque()
    result = []

    # Start with vertices of even degree
    for i in range(1, n + 1):
        if degree[i] % 2 == 0:
            queue.append(i)

    while queue:
        v = queue.popleft()
        result.append(v)

        # Destroy vertex v
        for neighbor in adj[v]:
            degree[neighbor] -= 1
            if degree[neighbor] % 2 == 0:
                queue.append(neighbor)

    if len(result) == n:
        print("YES")
