import sys

def longest_non_decreasing_subsequence(arr):
    """Find the length of the longest non-decreasing subsequence."""
    n = len(arr)
    dp = [1] * n

    for i in range(1, n):
        for j in range(i):
            if arr[i] >= arr[j]:
                dp[i] = max(dp[i], dp[j] + 1)

    return max(dp)

def solve(n, a):
    max_len = 0

    for i in range(n):
        for j in range(i, n):
            # Create a copy of the array
            arr = a.copy()
            arr[i:j+1] = arr[i:j+1][::-1]

            # Find the longest non-decreasing subsequence
            max_len = max(max_len, longest_non_decreasing_subsequence(arr))

    return max_len

