import sys

def is_subsequence(t, s):
    """Check if t is a subsequence of s"""
    it = iter(s)
    return all(c in it for c in t)

def solve(t):
    """Find the optimal string s for given t"""
    if len(t) == 0:
        return ""

    # If t consists of only one character, we can just return t
    if all(c == t[0] for c in t):
        return t

    # Try period 2
    for block in ["01", "10"]:  # Blocks of length 2
        # Try different number of repetitions
        for reps in range(1, 2 * len(t) + 1):
            s = block * reps
            if len(s) <= 2 * len(t) and is_subsequence(t, s):
                return s

    # If period 2 didn't work, try period equal to the length of t
    # This means we just repeat the string t itself
    return t * 2

T = int(sys.stdin.readline())
for _ in range(T):
    t = sys.stdin.readline().strip()
    print(solve(t))
"}

