import sys

def solve():
    MOD = 10**9 + 7
    t = int(sys.stdin.readline())
    results = []

    for _ in range(t):
        n, k = map(int, sys.stdin.readline().split())

        # Compute binomial coefficients C(n, i) for i = 0 to min(n, k-1)
        # We'll use DP to compute factorial and inverse factorial

        max_n = n
        fact = [1] * (max_n + 1)
        for i in range(1, max_n + 1):
            fact[i] = fact[i-1] * i % MOD

        inv_fact = [1] * (max_n + 1)
        inv_fact[max_n] = pow(fact[max_n], MOD-2, MOD)
        for i in range(max_n-1, -1, -1):
            inv_fact[i] = inv_fact[i+1] * (i+1) % MOD

        def comb(n, k):
            if k < 0 or k > n:
                return 0
            return fact[n] * inv_fact[k] % MOD * inv_fact[n - k] % MOD

        answer = 0
        for i in range(min(n, k-1) + 1):
            answer = (answer + comb(n, i)) % MOD

        results.append(answer)

    sys.stdout.write("\n".join(map(str, results)))

if __name__ == "__main__":
    solve()
"}

