def count_safe_codes(s):
    fixed_digits = set()
    letters = {}
    num_letters = 0
    num_wildcards = 0
    first_char_is_letter = False
    first_char_letter = None

    for i, ch in enumerate(s):
        if ch == '?':
            num_wildcards += 1
        elif ch.isdigit():
            fixed_digits.add(ch)
        else:  # ch is a letter (A-J)
            if ch in letters:
                # Already assigned, just check consistency
                pass
            else:
                letters[ch] = None
                num_letters += 1
                if i == 0:
                    first_char_is_letter = True
                    first_char_letter = ch

    # Check if any fixed digit conflicts with a letter
    for ch in letters:
        if ch in fixed_digits:
            return 0

    # Count valid assignments for letters
    if first_char_is_letter:
        # First letter cannot be 0
        if num_letters == 1:
            # Only one letter, which is the first character
            return 9 * (10 ** num_wildcards)
        else:
            # First letter has 9 choices (1-9)
            # Remaining letters have 9 * 8 * ... * (10 - num_letters + 1) choices
            if num_letters > 10:
                return 0
            return 9 * (9 * 8 * ... * (10 - num_letters + 1)) * (10 ** num_wildcards)
    else:
        # First character is not a letter
