def push(node, l, r):
    if tree_data[node] != 0:
        tree_data[node] = (r - l + 1) - tree_data[node]
        if l != r:
            tree_data[2 * node] ^= tree_data[node]
            tree_data[2 * node + 1] ^= tree_data[node]
        tree_data[node] = 0

def update_range(node, l, r, ul, ur):
    push(node, l, r)
    if ur < l or ul > r:
        return
    if ul <= l and r <= ur:
        tree_data[node] ^= (r - l + 1)
        push(node, l, r)
        return
    mid = (l + r) // 2
    update_range(2 * node, l, mid, ul, ur)
    update_range(2 * node + 1, mid + 1, r, ul, ur)
    tree_data[node] = tree_data[2 * node] + tree_data[2 * node + 1]

def query_range(node, l, r, ql, qr):
    push(node, l, r)
    if qr < l or ql > r:
        return 0
    if ql <= l and r <= qr:
        return tree_data[node]
    mid = (l + r) // 2
    return query_range(2 * node, l, mid, ql, qr) + query_range(2 * node + 1, mid + 1, r, ql, qr)

