import sys

def minimal_perimeter(a, b):
    """Find the minimal perimeter of a rectangle containing a red rectangle of area a
    and a blue rectangle of area b, with the constraint that either a or b can form a rectangle."""

    total_area = a + b
    min_perimeter = float('inf')

    # Try all possible heights for the red rectangle
    for h in range(1, int((a + b) ** 0.5) + 1):
        if a % h == 0:
            w_a = a // h
            # The blue rectangle area is (w_total - w_a) * h = b
            w_total = w_a + b // h
            if w_total * h == total_area:
                perimeter = 2 * (w_total + h)
                min_perimeter = min(min_perimeter, perimeter)

        if b % h == 0:
            w_b = b // h
            # The red rectangle area is w * h = a
            w = a // h
            # Blue rectangle area is (w_total - w) * h = b => w_total = w + b/h
            w_total = w + b // h
            if w_total * h == total_area:
                perimeter = 2 * (w_total + h)
                min_perimeter = min(min_perimeter, perimeter)

    # Also try all possible heights for the large rectangle
    for h in range(1, int((a + b) ** 0.5) + 1):
        w_total = (a + b) // h
        # Try all possible ways to place a rectangle of area a
        for h_a in range(1, h):
            if a % h_a == 0 and b % h_a == 0:
                w_a = a // h_a
                w_b = b // h_a
                if w_a + w_b == w_total:
                    perimeter = 2 * (w_total + h)
                    min_perimeter = min(min_perimeter, perimeter)
            if a % h == 0 and b % h == 0:
                w_a = a // h
                w_b = b // h
                if w_a + w_b == w_total:
                    perimeter = 2 * (w_total + h)
                    min_perimeter = min(min_perimeter, perimeter)

