def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:1+n]))

    # Try all possible orders and find the maximum
    max_result = -1
    best_order = []

    from itertools import permutations

    # Limit permutations to avoid TLE for large n
    if n <= 10:
        for perm in permutations(a):
            result = perm[0]
            for i in range(1, n):
                result = (result | perm[i]) - perm[i]
            if result > max_result:
                max_result = result
                best_order = perm
    else:
        # For larger n, use a greedy approach based on bit count
        # Sort by highest bit position (from highest to lowest)
        a.sort(key=lambda x: x.bit_length(), reverse=True)
        result = a[0]
        for i in range(1, n):
            result = (result | a[i]) - a[i]
        best_order = a

    print(' '.join(map(str, best_order)))

if __name__ == "__main__":
    solve()
