import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    m = int(data[1])

    # Read the matrix
    matrix = []
    idx = 2
    for i in range(n):
        row = data[idx:idx+m]
        matrix.append(row)
        idx += m

    # For each column, count how many rows have a 1
    ones_per_col = [0] * m
    for row in matrix:
        for col in range(m):
            if row[col] == '1':
                ones_per_col[col] += 1

    # For each column, find the rows that have a 1 in that column
    # and count how many columns have 1s in any of those rows
    best_area = 0

    for col in range(m):
        # Column with index col has ones_per_col[col] rows with 1s
        if ones_per_col[col] == 0:
            continue

        # Find all rows that have a 1 in this column
        selected_rows = [i for i, row in enumerate(matrix) if row[col] == '1']

        # Count how many columns have 1s in any of these rows
        common_cols = 0
        for c in range(m):
            for row in selected_rows:
                if matrix[row][c] == '1':
                    common_cols = 1
                    break

        area = ones_per_col[col] * common_cols
        best_area = max(best_area, area)

    print(best_area)

if __name__ == "__main__":
    solve()
