import sys
from collections import deque

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    p = list(map(int, data[1:n+1]))

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if p[i-1] != 0:
            adj[i].append(p[i-1])
            adj[p[i-1]].append(i)

    # Calculate initial degrees
    degrees = [0] * (n + 1)
    for i in range(1, n + 1):
        degrees[i] = len(adj[i])

    # Use BFS to find destruction order
    order = []
    visited = [False] * (n + 1)

    # Start with vertices that have even degree
    queue = deque()
    for i in range(1, n + 1):
        if degrees[i] % 2 == 0:
            queue.append(i)
            visited[i] = True

    while queue:
        u = queue.popleft()
        order.append(u)

        # This vertex is now destroyed
        visited[u] = True

        # Update degrees of neighbors
        for v in adj[u]:
            if not visited[v]:
                degrees[v] -= 1

                # If degree becomes even, it can be destroyed now
                if degrees[v] % 2 == 0:
                    queue.append(v)
                    visited[v] = True

