import sys
import math

def is_perfect_square(x):
    return int(math.isqrt(x)) ** 2 == x

def get_signature(x):
    # Get prime factorization
    factors = {}
    temp = x
    for i in range(2, int(math.isqrt(temp)) + 1):
        while temp % i == 0:
            factors[i] = factors.get(i, 0) + 1
            temp //= i
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # Convert to signature (even/odd exponents)
    return tuple((exp % 2) for exp in factors.values())

def solve():
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Check if any element is a perfect square
    if any(is_perfect_square(x) for x in a):
        print(1)
        return

    # Count signatures
    from collections import defaultdict
    signature_counts = defaultdict(int)
    for x in a:
        sig = get_signature(x)
        signature_counts[sig] += 1

    # Check if any signature appears at least twice
    for sig, count in signature_counts.items():
        if count >= 2:
            print(2)
            return

    # If we get here, no two elements have the same signature
    # We need to pick all elements to get a perfect square
    print(-1)

if __name__ == "__main__":
    solve()
