def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    A = data[1]

    # Extract digits
    digits = [int(c) for c in A]

    # Weights for each position
    weights = []
    for i in range(2 * n):
        if i % 2 == 0:  # Homer's turn (0-indexed, 1st, 3rd, 5th, ...)
            weight = 10 ** (n - 1 - i // 2)
        else:  # Marge's turn (0-indexed, 2nd, 4th, 6th, ...)
            weight = 10 ** (n - 2 - i // 2)
        weights.append((weight, i % 2))  # i%2 = 0 for Homer, 1 for Marge

    # Sort by weight descending
    weights.sort(reverse=True)

    # Sort digits descending
    digits.sort(reverse=True)

    # Assign digits to weights
    assignment = [None] * (2 * n)
    for i, (weight, player) in enumerate(weights):
        assignment[i] = (digits[i], player)

    # Reconstruct the sequence
    sequence = []
    for i in range(2 * n):
        # Find which player gets the i-th position
        if i % 2 == 0:
            # Homer's turn, we need to find the digit assigned to Homer's position
            # Find the assignment with player=0 at this position
            for j, (digit, p) in enumerate(assignment):
                if p == 0 and j == i:
                    sequence.append('H')
                    break
        else:
            # Marge's turn
            for j, (digit, p) in enumerate(assignment):
                if p == 1 and j == i:
                    sequence.append('M')
                    break

    print(''.join(sequence))

if __name__ == '__main__':
