def longest_common_subsequence(n, k, permutations):
    # For each element, track its position in each permutation
    positions = [[] for _ in range(n + 1)]
    for perm_idx, perm in enumerate(permutations):
        for elem, pos in enumerate(perm):
            positions[elem].append(pos)

    # We need to find the longest sequence where elements appear in increasing
    # order in all permutations simultaneously

    # Sort elements by the position in the first permutation
    sorted_elements = sorted(range(1, n + 1), key=lambda x: positions[x][0])

    # Check if this order is a common subsequence
    # We'll build the sequence greedily
    result = []
    for elem in sorted_elements:
        # Check if elem can follow the last element in result
        if not result:
            result.append(elem)
        else:
            last = result[-1]
            # Check if elem appears after last in all permutations
            all_before = True
            for perm_idx in range(k):
                if positions[last][perm_idx] > positions[elem][perm_idx]:
                    all_before = False
                    break
            if all_before:
                result.append(elem)

    return len(result)

