# Generate regular bracket sequences of length 2n recursively
def gen(pos, depth, open, close, n, stack, out, results):
    # pos: current position in the sequence
    # depth: current depth
    # open: number of open brackets left
    # close: number of close brackets left
    # n: n
    # stack: current brackets string (in a way that's valid)
    # out: recursive call

    if out:
        if pos == 2*n:
            if is_valid(stack):
                results.append(stack)
            return
        if depth == 0:
            gen(pos+1, 0, n, n-1, n, stack + '(', False, results)
        else:
            gen(pos+1, 0, n, n-1, n, stack + ')', False, results)
        gen(pos+1, depth, n, n-1, n, stack + '(', False, results)
    else:
        gen(pos+1, depth+1, n-1, n, n, stack + '(', True, results)
        gen(pos+1, depth, n, n-1, n, stack + ')', True, results)

