    result = []

    for i in range(1, n + 1):
        # Count how many lamps from 1 to i are off
        off_count = 0
        for j in range(1, i + 1):
            if state[j - 1] == '0':
                off_count += 1

        # If all are on already, no operations needed
        if off_count == 0:
            result.append(0)
            continue

        # We need to find the minimum number of subsets to toggle
        # Let's try to greedily choose subsets that affect the most lamps

