import sys

def solve():
    MOD = 10**9 + 7
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Count frequency of each number
    freq = {}
    for num in a:
        freq[num] = freq.get(num, 0) + 1

    # Count how many numbers are divisible by each d
    max_val = max(a)
    cnt = [0] * (max_val + 1)
    for num in a:
        for d in range(1, num + 1):
            if num % d == 0:
                cnt[d] += 1

    # Precompute powers of 2 up to n
    power2 = [1] * (n + 1)
    for i in range(1, n + 1):
        power2[i] = (power2[i-1] * 2) % MOD

    # Compute Möbius function
    mobius = [1] * (max_val + 1)
    is_prime = [True] * (max_val + 1)
    for p in range(2, max_val + 1):
        if is_prime[p]:
            for multiple in range(p, max_val + 1, p):
                is_prime[multiple] = False
                mobius[multiple] *= -1
            p_square = p * p
            for multiple in range(p_square, max_val + 1, p_square):
                mobius[multiple] = 0

    # Compute answer using inclusion-exclusion
    answer = 0
    for d in range(1, max_val + 1):
        # g(d) = sum_{k: d|k} μ(k/d) * f(k)
        # where f(k) = 2^cnt[k] - 1
        f_k = (power2[cnt[d]] - 1) % MOD
        answer = (answer + mobius[d] * f_k) % MOD

    print(answer)

if __name__ == "__main__":
    solve()

