    n = int(input())
    a = list(map(int, input().split()))

    # If no operation is performed, the total power is just the sum
    min_total = sum(a)

    # Try all possible operations
    for i in range(n):
        for j in range(n):
            if i == j:
                continue

            # Find all divisors of a[i]
            divisors = set()
            for d in range(1, int(a[i]**0.5) + 1):
                if a[i] % d == 0:
                    divisors.add(d)
                    divisors.add(a[i] // d)

            # Try each divisor
            for x in divisors:
                # Perform the operation
                new_a = a.copy()
                new_a[i] //= x
                new_a[j] *= x

                # Check if all powers remain positive
                if new_a[i] > 0 and new_a[j] > 0:
                    total = sum(new_a)
                    if total < min_total:
                        min_total = total

    print(min_total)

solve()
